function normalizeInsertValuesForDraft(values = {}) {
  const next = { ...values };
  if (next.type === "open_url" && !String(next.openUrl || "").trim()) {
    next.openUrl = "about:blank";
  }
  if (next.type === "open_program" && !String(next.programPath || "").trim()) {
    next.programPath = "notepad.exe";
  }
  if (next.type === "chrome") {
    next.chromeName = String(next.chromeName || "").trim() || "Chrome: capturar elemento";
    if (!String(next.chromeTargetValue || "").trim() && !String(next.chromeHtml || "").trim()) {
      next.chromeTargetMethod = next.chromeTargetMethod || "css";
      next.chromeTargetValue = "__capturar_elemento__";
      next.chromeActionType = next.chromeActionType || "clicar";
    }
  }
  if (next.type === "ocr_text" && !String(next.ocrText || "").trim()) {
    next.ocrText = "Texto para localizar";
  }
  return next;
}

function closeInsertPanelWithAnimation(panelElement) {
  const panelState = state.insertPanel;
  const targetOrder = Number(panelElement?.dataset.targetOrder ?? panelState?.targetOrder);
  if (!panelElement || !panelState) {
    state.insertPanel = null;
    renderCommandMap();
    return;
  }

  if (panelElement.classList.contains("is-closing")) {
    return;
  }

  panelElement.classList.add("is-closing");
  panelElement.closest(".command-flow-row")?.classList.add("is-insert-closing");
  const layoutSnapshot = captureCommandMapCardPositions();
  window.setTimeout(() => {
    if (state.insertPanel === panelState || Number(state.insertPanel?.targetOrder) === targetOrder) {
      state.commandMapFocusOrder = targetOrder;
      state.insertPanel = null;
      renderCommandMap({
        layoutSnapshot,
        layoutAnimationMode: "slide",
        preserveScroll: true,
        skipAutoFit: true,
        suppressFocusScroll: true,
      });
    }
  }, 260);
}

function playCommandMapBlockRemoval(cardElement) {
  if (!cardElement || cardElement.classList.contains("is-removing")) {
    return Promise.resolve();
  }

  cardElement.classList.add("is-removing");
  return new Promise((resolve) => {
    window.setTimeout(resolve, 190);
  });
}

function playInsertCreateAnimation(panelElement) {
  if (!panelElement || panelElement.classList.contains("is-creating")) {
    return Promise.resolve();
  }

  const rect = panelElement.getBoundingClientRect();
  state.createdBlockMorphRect = {
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height,
  };
  panelElement.classList.add("is-creating");
  return new Promise((resolve) => {
    window.setTimeout(resolve, 120);
  });
}

function animateCreatedBlockFromPreview(order) {
  const fromRect = state.createdBlockMorphRect;
  if (!fromRect) {
    return false;
  }

  const card = commandMapList?.querySelector(`.command-tree-card[data-order="${order}"]`);
  if (!card) {
    return false;
  }

  const toRect = card.getBoundingClientRect();
  if (!toRect.width || !toRect.height) {
    return false;
  }

  const deltaX = fromRect.left - toRect.left;
  const deltaY = fromRect.top - toRect.top;
  const scaleX = Math.max(0.72, Math.min(1.35, fromRect.width / toRect.width));
  const scaleY = Math.max(0.72, Math.min(1.35, fromRect.height / toRect.height));
  const fromTransform = `translate(${deltaX}px, ${deltaY}px) scale(${scaleX}, ${scaleY})`;

  card.classList.remove("is-newly-created");
  card.classList.add("is-morph-created");
  card.style.transformOrigin = "top left";
  card.style.willChange = "transform, opacity";

  if (card.__commandMapShiftAnimation) {
    card.__commandMapShiftAnimation.cancel();
    card.__commandMapShiftAnimation = null;
  }

  const cleanup = () => {
    card.classList.remove("is-morph-created");
    card.style.transformOrigin = "";
    card.style.willChange = "";
    card.style.transform = "";
    card.style.opacity = "";
    card.__commandMapShiftAnimation = null;
    state.createdBlockMorphRect = null;
  };

  if (typeof card.animate === "function") {
    const animation = card.animate(
      [
        {
          opacity: 0.82,
          transform: fromTransform,
        },
        {
          opacity: 1,
          transform: "translate(0px, -3px) scale(1.015, 1.015)",
          offset: 0.62,
        },
        {
          opacity: 1,
          transform: "translate(0px, 0px) scale(1, 1)",
        },
      ],
      {
        duration: 420,
        easing: "cubic-bezier(0.16, 1, 0.3, 1)",
        fill: "both",
      }
    );
    card.__commandMapShiftAnimation = animation;
    animation.addEventListener("finish", cleanup, { once: true });
    animation.addEventListener("cancel", cleanup, { once: true });
    return true;
  }

  card.style.transition = "transform 420ms cubic-bezier(0.16, 1, 0.3, 1), opacity 280ms ease";
  card.style.opacity = "0.82";
  card.style.transform = fromTransform;
  requestAnimationFrame(() => {
    card.style.opacity = "";
    card.style.transform = "";
  });
  window.setTimeout(cleanup, 460);
  return true;
}

async function persistCommandMapDrafts() {
  const focusedOrder = Number(state.commandMapFocusOrder);
  if (!Number.isFinite(focusedOrder) || focusedOrder <= 0) {
    return;
  }

  const card = commandMapList?.querySelector(`.command-tree-card[data-order="${focusedOrder}"]`);
  if (!card) {
    return;
  }

  const order = Number(card.dataset.order);
  const type = card.dataset.type;
  const values = treeValuesFromCard(card);
  const roadmap = await invokeCommandCardUpdate({ order, type, values });

  if (roadmap) {
    applyRoadmap(roadmap);
    await refreshAutomationLibrary();
    await refreshTestLoopData();
  }
}

async function saveEntireCommandMap() {
  try {
    setCommandMapSaveState({
      running: true,
      dirty: true,
      percent: 0,
      status: "Salvando todo o mapa...",
    });

    const result = await persistCommandMapDraftsForExecution({
      onProgress: ({ current, total, percent }) => {
        const status = total
          ? `Salvando blocos ${current}/${total} para preparar o loop.`
          : "Nenhuma alteracao pendente no mapa.";
        setCommandMapSaveState({
          running: total > 0 && current < total,
          percent,
          status,
        });
      },
    });

    if (!result.total) {
      setCommandMapSaveState({
        running: false,
        dirty: false,
        percent: 100,
        status: "Mapa ja estava salvo e pronto para o loop.",
      });
      setMessage("Mapa ja estava salvo e pronto para o loop.", "success");
      return;
    }

    setCommandMapSaveState({
      running: false,
      dirty: false,
      percent: 100,
      status: `Mapa salvo com sucesso. ${result.saved} bloco(s) pronto(s) para o loop.`,
    });
    setMessage("Mapa salvo com sucesso e pronto para o loop.", "success");
  } catch (error) {
    setCommandMapSaveState({
      running: false,
      dirty: true,
      status: `Falha ao salvar o mapa: ${String(error)}`,
    });
    throw error;
  }
}

async function persistVisibleRecognitionDrafts() {
  const cards = getDistinctCommandTreeCards('.command-tree-card[data-type="clicar_imagem"]');
  if (!cards.length) {
    return;
  }

  for (const card of cards) {
    const order = Number(card.dataset.order);
    if (!Number.isFinite(order) || order <= 0) {
      continue;
    }

    const values = treeValuesFromCard(card);
    if (!String(values.imagePath || "").trim()) {
      continue;
    }

    const roadmap = await invoke("update_image_click_block", {
      order,
      imagem: values.imagePath,
      timeout: values.timeout,
      confianca: values.confidence,
      perfilBusca: values.searchProfile,
      modoAreaBusca: "target_window",
      areaBuscaX: 0,
      areaBuscaY: 0,
      areaBuscaLargura: 0,
      areaBuscaAltura: 0,
      janelaAlvo: values.windowTitle?.trim() || null,
      textoOcrEsperado: values.expectedOcrText?.trim() || null,
      modoReconhecimento: values.recognitionMode || "imagem",
      textoOcrBusca: values.ocrText?.trim() || null,
      acaoOcr: values.ocrAction || "clicar",
      salvarOcrEm: values.ocrSaveAs?.trim() || null,
      varreduraScroll: Boolean(values.ocrScrollEnabled),
      varreduraScrollTentativas: values.ocrScrollAttempts,
      varreduraScrollPixels: values.ocrScrollPixels,
      varreduraScrollDirecao: values.ocrScrollDirection,
      ...relativeOcrInvokeArgs(values),
      clicar: recognitionClicksFromMode(values.recognitionClickMode, 1) > 0,
      clicks: recognitionClicksFromMode(values.recognitionClickMode, 1),
      offsetX: values.clickOffsetX,
      offsetY: values.clickOffsetY,
      aoNaoEncontrar: values.failureAction,
      sequenciaNaoEncontrar: values.failureAction === "ir_para_sequencia"
        ? values.failureSequence.trim() || null
        : null,
      blocoNaoEncontrar: optionalPositiveInt(values.failureBlock),
      quantidadeTentativas: values.retryCount,
      intervaloTentativas: values.retryInterval,
      delay: values.delay,
    });
    if (roadmap) {
      applyRoadmap(roadmap);
    }
  }

  await refreshAutomationLibrary();
  await refreshTestLoopData();
}

function focusEditorBlock(order) {
  setWorkspaceTab("commands");
  requestAnimationFrame(() => {
    setCommandMapFocus(order, "auto");
    const target = commandMapList?.querySelector(`.command-tree-card[data-order="${order}"]`);
    if (target) {
      target.scrollIntoView({ behavior: "smooth", block: "center" });
      target.style.boxShadow = "0 0 0 1px rgba(223, 109, 58, 0.42), 0 0 0 10px rgba(223, 109, 58, 0.1)";
      setTimeout(() => {
        target.style.boxShadow = "";
      }, 1400);
    }
  });
}

